import glob
import pandas as pd

DATA = "/Users/Sergey/zeteo-runs/control-unseen/data"

for path in sorted(glob.glob(f"{DATA}/*.parquet")):
    df = pd.read_parquet(path)
    print("==", path.split("/")[-1])
    for col in df.columns:
        s = df[col].astype(str)
        hits = s[s.str.contains("00330", regex=False)]
        if len(hits):
            print(f"  col {col}: {len(hits)} hits, e.g. {hits.unique()[:5].tolist()}")
    if "functional_location" in df.columns:
        print("  sample functional_location:", df["functional_location"].astype(str).drop_duplicates().head(5).tolist())
    if "point" in df.columns:
        print("  sample point:", df["point"].astype(str).drop_duplicates().head(5).tolist())
        print("  point dtype:", df["point"].dtype)

